func:
// Amorçage. Le cœur du BMS vit dans lib/bms-core/ et est chargé par
// settings.js (functionGlobalContext.bmsCore) — code éditable, diffable et
// testable, au lieu de 75 000 caractères dans une chaîne JSON.
//
// À savoir : les modules sont lus au démarrage de Node-RED. Après une
// modification de lib/bms-core/, redéployer ne suffit pas — il faut redémarrer.

const core = global.get('bmsCore');
if (!core) {
    const hint = "bmsCore introuvable. Ajoutez  bmsCore: require('./lib/bms-core')  "
               + "dans functionGlobalContext de settings.js, copiez lib/ dans le userDir, "
               + "puis redémarrez Node-RED.";
    node.error(hint);
    node.status({ fill: 'red', shape: 'ring', text: 'bmsCore manquant' });
    return null;
}

const { bacnetPoints, virtualPoints } = core.installAll({ global, node, env });

// Count points
const sensorCount = Object.values(bacnetPoints).filter(p => p.access === 'read_only').length;
const actuatorCount = Object.values(bacnetPoints).filter(p => p.access === 'read_write').length;
const virtualCount = Object.keys(virtualPoints).length;

node.warn(`✓ AI BMS V12 Initialized: ${sensorCount} sensors, ${actuatorCount} actuators, ${virtualCount} virtual points + BMS API`);
node.status({ fill: 'green', shape: 'dot', text: `${sensorCount}S/${actuatorCount}A/${virtualCount}V` });

return msg;

const BMS = global.get('BMS');
const cache = global.get('myStateCache');
const states = global.get('stateRegistry') || [];
let facts = BMS ? BMS.getValues() : {};
if (cache) { states.forEach(s => { let v = cache.get(s.id); facts[s.id] = (v !== undefined) ? v : s.defaultValue; }); }
else { states.forEach(s => { facts[s.id] = s.defaultValue; }); }
msg.payload = facts;
return msg;

const { Engine } = global.get('jsonRulesEngine');
// allowUndefinedFacts: an unknown fact id must not reject the whole run (one bad AI rule would kill all automation)
const engine = new Engine([], { allowUndefinedFacts: true });
const groups = global.get('ruleGroups') || [];

// Initialize rule tracking
if (!global.get('ruleFireLog')) {
    global.set('ruleFireLog', {});
}
const fireLog = global.get('ruleFireLog');

// Fact-to-fact comparison. json-rules-engine operators receive ONLY (factValue, jsonValue) — no
// almanac — so a custom operator cannot resolve a second fact. Instead we PRE-RESOLVE: before each
// run we rewrite *Fact conditions into standard operators, substituting the live value of the
// referenced fact (from the facts object). `value` may be a fact id OR { fact, add?, subtract?,
// multiply?, divide? } for deadband/offset (e.g. temp > comfort_sp + 2 in one condition).
const facts = msg.payload || {};
const FACT_OPS = { lessThanFact: 'lessThan', greaterThanFact: 'greaterThan', lessThanInclusiveFact: 'lessThanInclusive', greaterThanInclusiveFact: 'greaterThanInclusive', equalFact: 'equal', notEqualFact: 'notEqual' };
function resolveVal(v) {
    if (v && typeof v === 'object' && v.fact) {
        let n = facts[v.fact];
        if (n === undefined || n === null) return undefined;
        if (v.add !== undefined) n += v.add;
        if (v.subtract !== undefined) n -= v.subtract;
        if (v.multiply !== undefined) n *= v.multiply;
        if (v.divide !== undefined && v.divide !== 0) n /= v.divide;
        return n;
    }
    const r = facts[v];
    return (r === undefined || r === null) ? undefined : r;
}
function transformConds(c) {
    if (!c || typeof c !== 'object') return c;
    if (Array.isArray(c.all)) c.all = c.all.map(transformConds);
    if (Array.isArray(c.any)) c.any = c.any.map(transformConds);
    if (c.operator && FACT_OPS[c.operator]) {
        const rv = resolveVal(c.value);
        if (rv === undefined) return { fact: '__unresolved__', operator: 'equal', value: '__never__' }; // can't compare -> never fire
        return { fact: c.fact, operator: FACT_OPS[c.operator], value: rv };
    }
    return c;
}

let ruleCount = 0, errorCount = 0;
groups.forEach(g => {
    if (g.rules && g.enabled !== false) {
        g.rules.forEach(r => {
            try {
                if (!r.conditions || (!r.conditions.all && !r.conditions.any)) {
                    throw new Error('conditions must have "all" or "any" array');
                }
                if (!r.event || !r.event.type) {
                    throw new Error('event must have "type" field');
                }
                const rule = JSON.parse(JSON.stringify(r));
                rule.conditions = transformConds(rule.conditions);   // resolve *Fact -> standard ops with live values
                rule.name = '[' + g.name + '] ' + rule.name;
                rule.priority = rule.priority || 1;

                // Add onSuccess handler for tracking
                rule.onSuccess = function(event, almanac, ruleResult) {
                    fireLog[rule.name] = {
                        lastFired: Date.now(),
                        event: event
                    };
                    global.set('ruleFireLog', fireLog);
                };

                engine.addRule(rule);
                ruleCount++;
            } catch(e) {
                errorCount++;
                if (errorCount <= 3) node.warn('Rule "' + (r.name||'?') + '": ' + e.message);
            }
        });
    }
});

if (errorCount > 3) node.warn('... and ' + (errorCount - 3) + ' more rule errors');
if (ruleCount === 0 && groups.length > 0) node.warn('No valid rules loaded! Check rule format.');

node.status({ fill: 'green', shape: 'dot', text: ruleCount + ' rules loaded' });

engine.run(msg.payload).then(results => {
    results.events.forEach(e => { 
        node.send({ topic: e.type, payload: e.params }); 
    });
    if (results.events.length > 0) {
        node.status({ fill: 'blue', shape: 'dot', text: results.events.length + ' events fired' });
    }
}).catch(err => { node.error('Engine: ' + err.message); });
return null;

const NodeCache = global.get('nodeCacheModule');
const stateRegistry = global.get('stateRegistry') || [];
const BMS = global.get('BMS');

if (!global.get('myStateCache')) {
    global.set('myStateCache', new NodeCache());
}
const cache = global.get('myStateCache');

const stateId = msg.payload.id;
const def = stateRegistry.find(s => s.id === stateId);

const registryTTL = (def && def.ttl) ? def.ttl : 0;
const effectiveTTL = (msg.payload.ttl !== undefined) ? msg.payload.ttl : registryTTL;

let newValue;

if (msg.payload.value_expr) {
    const expr = msg.payload.value_expr;
    const allFacts = BMS ? BMS.getValues() : {};
    stateRegistry.forEach(s => {
        const v = cache.get(s.id);
        allFacts[s.id] = (v !== undefined) ? v : s.defaultValue;
    });

    let baseValue = 0;
    if (expr.fact) {
        baseValue = allFacts[expr.fact];
        if (baseValue === undefined) {
            node.warn('value_expr: fact "' + expr.fact + '" not found, using 0');
            baseValue = 0;
        }
    } else if (expr.value !== undefined) {
        baseValue = expr.value;
    }

    // operands may be a constant (add/multiply/…) OR another fact (*_from_fact) so timeouts/
    // limits can be driven by a configurable state instead of a hard-coded number.
    const operand = function(key) {
        if (expr[key] !== undefined) return expr[key];
        const ff = expr[key + '_from_fact'];
        if (ff !== undefined) { const v = allFacts[ff]; return (v === undefined) ? 0 : v; }
        return undefined;
    };
    newValue = baseValue;
    let v;
    if ((v = operand('add')) !== undefined) newValue = newValue + v;
    if ((v = operand('subtract')) !== undefined) newValue = newValue - v;
    if ((v = operand('multiply')) !== undefined) newValue = newValue * v;
    if ((v = operand('divide')) !== undefined && v !== 0) newValue = newValue / v;
    if ((v = operand('min')) !== undefined && newValue < v) newValue = v;
    if ((v = operand('max')) !== undefined && newValue > v) newValue = v;
    if (expr.round === true) newValue = Math.round(newValue);
    else if (expr.round === 'floor') newValue = Math.floor(newValue);
    else if (expr.round === 'ceil') newValue = Math.ceil(newValue);

} else if (msg.payload.value_from_fact) {
    const factId = msg.payload.value_from_fact;
    const allFacts = BMS ? BMS.getValues() : {};
    stateRegistry.forEach(s => {
        const v = cache.get(s.id);
        allFacts[s.id] = (v !== undefined) ? v : s.defaultValue;
    });

    if (allFacts[factId] !== undefined) {
        newValue = allFacts[factId];
    } else {
        node.warn('value_from_fact: "' + factId + '" not found, ignoring set_state');
        return null;
    }
} else {
    newValue = msg.payload.value;
}

cache.set(stateId, newValue, effectiveTTL);

const ttlStr = effectiveTTL > 0 ? ' (TTL: ' + effectiveTTL + 's)' : '';
node.status({fill: 'green', shape: 'dot', text: stateId + ' = ' + newValue + ttlStr});

return null;

const tag = msg.payload.tag;
const metadata = global.get('bmsMetadata') || {};
const bacnetPoints = global.get('bacnetPoints') || {};
const virtualPoints = global.get('virtualPoints') || {};

let targetValue = msg.payload.value;
let sourceUnit = msg.payload.unit || null;  // ← NEW: explicit unit parameter

// Resolve value_from_fact if specified
if (msg.payload.value_from_fact) {
    const factId = msg.payload.value_from_fact;
    if (bacnetPoints[factId]) {
        targetValue = bacnetPoints[factId].value;
        if (!sourceUnit) sourceUnit = bacnetPoints[factId].units;  // Infer if not explicit
    } else if (virtualPoints[factId]) {
        targetValue = virtualPoints[factId].value;
        if (!sourceUnit) sourceUnit = virtualPoints[factId].units;
    } else {
        const cache = global.get('myStateCache');
        const stateRegistry = global.get('stateRegistry') || [];
        const stateDef = stateRegistry.find(s => s.id === factId);
        if (cache) {
            targetValue = cache.get(factId);
            if (targetValue === undefined && stateDef) {
                targetValue = stateDef.defaultValue;
            }
        }
    }
}

// Never fan out an unresolved value to actuators
if (targetValue === undefined) {
    node.warn('control_group tag="' + tag + '": value could not be resolved, ignoring command');
    node.status({ fill: 'yellow', shape: 'ring', text: tag + ': unresolved value' });
    return null;
}

// Determine expected unit type for filtering
let expectedUnitType = null;
if (sourceUnit) {
    expectedUnitType = sourceUnit;
} else if (typeof targetValue === 'boolean') {
    expectedUnitType = 'bool';
}

let matchCount = 0;
let skippedCount = 0;

Object.entries(metadata).forEach(([id, meta]) => {
    if (!meta.tags || !meta.tags.includes(tag)) return;
    const point = bacnetPoints[id];
    if (!point || point.access !== 'read_write') return;

    const pointUnit = point.units;
    let compatible = true;

    // Unit compatibility check
    if (expectedUnitType) {
        compatible = (pointUnit === expectedUnitType);
    } else if (typeof targetValue === 'boolean') {
        compatible = (pointUnit === 'bool');
    } else if (typeof targetValue === 'number' && pointUnit === 'bool') {
        compatible = false;  // Don't send numbers to boolean actuators
    }

    if (compatible) {
        matchCount++;
        node.send({
            topic: 'control_device',
            payload: { id: id, value: targetValue, _source: 'group_resolver', _tag: tag }
        });
    } else {
        skippedCount++;
    }
});

// Status reporting
if (matchCount === 0 && skippedCount > 0) {
    node.warn(`control_group tag="${tag}": no compatible actuators (${skippedCount} skipped - unit mismatch with ${expectedUnitType || typeof targetValue})`);
    node.status({ fill: 'yellow', shape: 'ring', text: `${tag}: 0 matched, ${skippedCount} skipped` });
} else if (matchCount === 0) {
    node.warn(`control_group tag="${tag}": no actuators found with this tag`);
    node.status({ fill: 'red', shape: 'ring', text: `${tag}: not found` });
} else {
    node.status({ fill: 'green', shape: 'dot', text: `${tag}: ${matchCount} updated` });
}

return null;

const BMS = global.get('BMS');
if (!BMS) return null;

let targetValue = msg.payload.value;

// Resolve value_from_fact if specified
if (msg.payload.value_from_fact) {
    const factId = msg.payload.value_from_fact;
    const allValues = BMS.getValues();
    if (allValues[factId] !== undefined) {
        targetValue = allValues[factId];
    } else {
        node.warn('value_from_fact "' + factId + '" not found, ignoring command');
        return null;
    }
}

// Écriture par la couche pilote. En mode simulé elle aboutit dans le tick
// courant ; en mode BACnet c'est une requête réseau qui peut échouer, expirer
// ou être refusée par l'automate. On n'attend pas la confirmation (le moteur de
// règles est en « tire et oublie »), mais tout échec est tracé.
const pointId = msg.payload.id;
BMS.writeValueAsync(pointId, targetValue)
    .then(res => {
        if (res && res.ok) {
            node.status({ fill: 'green', shape: 'dot', text: pointId + ' = ' + targetValue });
        } else {
            const why = (res && res.error) || 'refusé';
            node.status({ fill: 'yellow', shape: 'ring', text: pointId + ' — ' + why });
            const safety = global.get('bmsSafety');
            if (safety) safety.record(pointId, targetValue, 'rule', { ok: false, error: why });
        }
    })
    .catch(e => {
        node.status({ fill: 'red', shape: 'ring', text: pointId + ' — ' + e.message });
        const safety = global.get('bmsSafety');
        if (safety) safety.record(pointId, targetValue, 'rule', { ok: false, error: e.message });
    });

return { payload: 'commanded', id: pointId, value: targetValue };

const config = global.get('dashboardConfig') || { widgets: [] };
const BMS = global.get('BMS');
const cache = global.get('myStateCache');
const states = global.get('stateRegistry') || [];
let data = BMS ? BMS.getValues() : {};
if (cache) { states.forEach(s => { let v = cache.get(s.id); data[s.id] = (v !== undefined) ? v : s.defaultValue; }); }
msg.ui_config = config;
msg.payload = data;
return msg;

if (!msg.payload || typeof msg.payload !== 'object' || msg.payload.id === undefined) return [null, null];

if (msg.topic === 'control') {
    const id = msg.payload.id;
    const value = msg.payload.value;

    // Soft states (st_*) go to the State Manager; hardware goes through the Safety Guard
    if (id && id.startsWith('st_')) {
        return [null, {
            topic: 'set_state',
            payload: { id: id, value: value }
        }];
    }

    return [{
        payload: { id: id, value: value }
    }, null];
}

return [null, null];

const SunCalc = global.get('suncalcModule');
const BMS = global.get('BMS');
const vp = global.get('virtualPoints') || {};
const lat = vp['loc_latitude']?.value || 48.8566;
const lon = vp['loc_longitude']?.value || 2.3522;
if (!SunCalc) return null;
const now = (BMS && BMS.now) ? BMS.now() : new Date();   // horloge système (cf. mode Démo/Test)
const times = SunCalc.getTimes(now, lat, lon);
const toMin = d => d.getHours() * 60 + d.getMinutes();
const sr = toMin(times.sunrise), ss = toMin(times.sunset);
const day = now >= times.sunrise && now <= times.sunset;
const pos = SunCalc.getPosition(now, lat, lon);
const alt = Math.round(pos.altitude * 180 / Math.PI * 10) / 10;
const azi = Math.round(pos.azimuth * 180 / Math.PI * 10) / 10;
if (BMS) { BMS.setVirtualValue('sun_sunrise_minutes', sr); BMS.setVirtualValue('sun_sunset_minutes', ss); BMS.setVirtualValue('sun_is_daylight', day); BMS.setVirtualValue('sun_altitude', alt); BMS.setVirtualValue('sun_azimuth', azi); }
global.set('buildingLocation', { latitude: lat, longitude: lon });
const fmt = d => d.toLocaleTimeString('en-GB', {hour:'2-digit', minute:'2-digit'});
node.status({fill: day ? 'yellow' : 'blue', shape: 'dot', text: '☀ ' + fmt(times.sunrise) + ' | 🌙 ' + fmt(times.sunset) + ' @ ' + lat.toFixed(2) + ',' + lon.toFixed(2)});
return msg;

const build = global.get('buildAIPrompt');
if (!build) { node.warn('buildAIPrompt not initialized - press Boot System'); return null; }
msg.payload = build('paste');
msg.topic = 'prompt_generated';
return msg;

let input = (msg.payload || '').toString();

// Strip // and /* */ comments WITHOUT touching string contents (a URL in a
// description must survive \u2014 the old regex truncated anything containing //)
function stripJsonComments(s) {
    let out = '', inStr = false, esc = false;
    for (let i = 0; i < s.length; i++) {
        const c = s[i], n = s[i + 1];
        if (inStr) {
            out += c;
            if (esc) esc = false;
            else if (c === '\\') esc = true;
            else if (c === '"') inStr = false;
        } else if (c === '"') { inStr = true; out += c; }
        else if (c === '/' && n === '/') { while (i < s.length && s[i] !== '\n') i++; out += '\n'; }
        else if (c === '/' && n === '*') { i += 2; while (i < s.length && !(s[i] === '*' && s[i + 1] === '/')) i++; i++; }
        else out += c;
    }
    return out;
}

let cleanedInput = stripJsonComments(input.replace(/\r\n/g, '\n'))
    .replace(/,(\s*[}\]])/g, '$1')
    .replace(/\u00A0/g, ' ')
    .trim();

let jsonString = '';
const match = cleanedInput.match(/```(?:json)?([\s\S]*?)```/);
if (match) jsonString = match[1].trim();
else if (cleanedInput.startsWith('{')) jsonString = cleanedInput;
else { 
    const f = cleanedInput.indexOf('{'); 
    const l = cleanedInput.lastIndexOf('}'); 
    if (f !== -1 && l > f) jsonString = cleanedInput.substring(f, l + 1); 
}

try {
    if (!jsonString) throw new Error('No JSON found');
    const cfg = JSON.parse(jsonString);

    const BMS = global.get('BMS');
    if (!BMS || !BMS.applyConfig) throw new Error('BMS not initialized');
    const result = BMS.applyConfig(cfg);
    if (result.errors.length > 0) throw new Error(result.errors.join('; '));

    const info = [];
    if (result.counts.agents !== undefined) info.push(result.counts.agents + ' agents');
    if (result.counts.groups !== undefined) info.push(result.counts.groups + ' groups (' + result.counts.rules + ' rules)');
    if (result.counts.states !== undefined) info.push(result.counts.states + ' states');
    if (result.counts.widgets !== undefined) info.push(result.counts.widgets + ' widgets');
    if (result.unknownFacts.length > 0) {
        info.push('⚠ unknown facts (rules referencing them will never fire): ' + result.unknownFacts.join(', '));
        node.warn('Unknown facts in applied config: ' + result.unknownFacts.join(', '));
    }

    node.warn('✓ Applied: ' + info.join(', '));
    return [{ payload: (result.unknownFacts.length > 0 ? '⚠️ ' : '✅ ') + info.join(', ') }, { payload: 'refresh' }];
} catch (e) {
    node.error('Parse error: ' + e.message);
    return [{ payload: '❌ ' + e.message }, null];
}

const agents = global.get('behaviorAgents') || [];
const groups = global.get('ruleGroups') || [];
const states = global.get('stateRegistry') || [];
const cache = global.get('myStateCache');
const fireLog = global.get('ruleFireLog') || {};

const agentView = agents.map(a => {
    let ag = [];

    // Method 1: agent.rule_group_ids (array)
    if (a.rule_group_ids && Array.isArray(a.rule_group_ids)) {
        ag = groups.filter(g => a.rule_group_ids.includes(g.id));
    }
    // Method 2: agent.rule_group (singular string)
    else if (a.rule_group && typeof a.rule_group === 'string') {
        ag = groups.filter(g => g.id === a.rule_group);
    }
    // Method 3: group.behavior_agent (reverse lookup)
    else {
        ag = groups.filter(g => g.behavior_agent === a.id);
    }

    // Enrich rules with fire log data
    ag = ag.map(g => {
        const enrichedRules = (g.rules || []).map(r => {
            const fullName = '[' + g.name + '] ' + r.name;
            const logEntry = fireLog[fullName];
            return {
                ...r,
                _lastFired: logEntry ? logEntry.lastFired : null,
                _lastEvent: logEntry ? logEntry.event : null
            };
        });
        return { ...g, rules: enrichedRules };
    });

    return { 
        agent: a, 
        rule_groups: ag, 
        totalRules: ag.reduce((s, g) => s + (g.rules || []).length, 0) 
    };
});

// Detect timer states structurally: any state written from a minute-clock fact via value_expr
// (the timer pattern). Records WHICH clock so the countdown uses the right base — minute_of_week
// or the wrap-safe monotonic glob_time_epoch_min.
const TIMER_FACTS = ['glob_time_minute_of_week', 'glob_time_epoch_min'];
const timerBaseById = {};   // stateId -> clock fact id
groups.forEach(g => (g.rules || []).forEach(r => {
    const ev = r.event;
    if (ev && ev.type === 'set_state' && ev.params) {
        const ve = ev.params.value_expr;
        if (ve && TIMER_FACTS.indexOf(ve.fact) !== -1) timerBaseById[ev.params.id] = ve.fact;
        if (TIMER_FACTS.indexOf(ev.params.value_from_fact) !== -1) timerBaseById[ev.params.id] = ev.params.value_from_fact;
    }
}));

// Current values of both minute clocks (computed like "Update time") + sub-minute seconds, so the
// countdown hits zero exactly when the greaterThanFact off-rule fires.
const _now = new Date();
const _dow = _now.getDay() === 0 ? 7 : _now.getDay();
const _clockNow = {
    glob_time_minute_of_week: (_dow - 1) * 1440 + _now.getHours() * 60 + _now.getMinutes(),
    glob_time_epoch_min: Math.floor(_now.getTime() / 60000)
};
const _secs = _now.getSeconds();

const liveStates = states.map(s => {
    let cv = s.defaultValue;
    if (cache) {
        const v = cache.get(s.id);
        if (v !== undefined) cv = v;
    }
    const isTimer = !!timerBaseById[s.id];
    let remainingSeconds = null;
    if (isTimer && typeof cv === 'number' && cv > 0) {
        remainingSeconds = (cv - _clockNow[timerBaseById[s.id]]) * 60 - _secs;
        if (remainingSeconds < 0) remainingSeconds = 0;
    }
    return {
        id: s.id,
        name: s.name || s.id,
        type: s.type,
        defaultValue: s.defaultValue,
        currentValue: cv,
        ttl: s.ttl,
        isTimer: isTimer,
        remainingSeconds: remainingSeconds
    };
});

msg.payload = { agents: agentView, liveStates: liveStates };
return msg;

const bacnet = global.get('bacnetPoints') || {};
const meta = global.get('bmsMetadata') || {};
const grouped = {};

Object.entries(bacnet).forEach(([id, p]) => {
    if (p.access !== 'read_only') return;
    if (id === 'glob_outside_temp' || id === 'glob_outside_lux') return;

    const m = meta[id] || { tags: [], zone: 'misc' };
    const floor = (m.tags || []).find(t => t.startsWith('floor')) || 'global';
    const zone = m.zone || 'misc';

    if (!grouped[floor]) grouped[floor] = {};
    if (!grouped[floor][zone]) grouped[floor][zone] = [];

    // Detect type from units - 'bool' means boolean sensor
    const isBoolean = (p.units === 'bool');

    grouped[floor][zone].push({ 
        id, 
        name: p.objectName, 
        type: isBoolean ? 'boolean' : 'analog',  // Fixed: derive type from units
        value: p.value,      // Fixed: use 'value' not 'presentValue'
        units: p.units 
    });
});

msg.payload = grouped;
return msg;

// Forçage d'un capteur depuis le panneau « Sensor Simulation ».
//
// Ce panneau pilote le SIMULATEUR PHYSIQUE, pas un automate. Passer par BACnet
// n'aurait pas de sens : sur le réseau une mesure est une entrée en lecture
// seule, et c'est correct. Mais un simulateur doit pouvoir être piloté — c'est
// sa raison d'être. On s'adresse donc à son canal de contrôle hors-bande, en
// amont de BACnet. La valeur repart ensuite vers le BMS par notification COV,
// comme n'importe quelle mesure.

if (msg.topic !== 'sensor_update') return null;

const { id, value } = msg.payload || {};
if (!id) return null;

const mode = global.get('bacnetMode');
const target = global.get('bacnetTarget') || {};

if (mode !== 'simulated') {
    node.status({ fill: 'yellow', shape: 'ring', text: 'capteurs non forçables' });
    node.warn(mode === 'real'
        ? 'Forçage refusé : « ' + id + ' » est une mesure d’un automate réel.'
        : 'Forçage impossible : aucun serveur BACnet connecté.');
    return null;
}

const url = 'http://' + (target.host || '127.0.0.1') + ':' + (target.controlPort || 47811) + '/force';
const fetchFn = global.get('fetchFn');

fetchFn(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ id: id, value: value })
}).then(r => r.json().then(b => ({ ok: r.ok, b })))
  .then(({ ok, b }) => {
      if (ok) node.status({ fill: 'green', shape: 'dot', text: id + ' = ' + b.value });
      else {
          node.status({ fill: 'yellow', shape: 'ring', text: id + ' — ' + (b.error || 'refusé') });
          node.warn('forçage refusé par le simulateur : ' + (b.error || 'inconnu'));
      }
  })
  .catch(e => {
      node.status({ fill: 'red', shape: 'ring', text: 'simulateur injoignable' });
      node.warn('canal de contrôle du simulateur injoignable (' + url + ') : ' + e.message);
  });

return null;

const BMS = global.get('BMS');
if (!BMS) return null;
msg.payload = BMS.getValues();
return msg;

const BMS = global.get('BMS');
if (!BMS) return null;

// Persist location + physics toggle to the 'file' store so they survive restarts
// (Initialize System overlays them at boot)
function persistSettings() {
    try {
        const vp = global.get('virtualPoints') || {};
        const saved = {};
        ['loc_city', 'loc_country', 'loc_latitude', 'loc_longitude', 'loc_timezone', 'physics_enabled'].forEach(k => {
            if (vp[k]) saved[k] = vp[k].value;
        });
        global.set('locationSettings', saved, 'file');
    } catch (e) { /* file store not configured */ }
}

if (msg.topic === 'update_location' && msg.payload) {
    const loc = msg.payload;
    if (loc.city) BMS.writeValue('loc_city', loc.city);
    if (loc.country) BMS.writeValue('loc_country', loc.country);
    if (loc.latitude !== undefined) BMS.writeValue('loc_latitude', loc.latitude);
    if (loc.longitude !== undefined) BMS.writeValue('loc_longitude', loc.longitude);
    persistSettings();
    node.status({ fill: 'green', shape: 'dot', text: 'Location: ' + (loc.mode === 'city' ? loc.city + ', ' + loc.country : loc.latitude + ', ' + loc.longitude) });
    return { payload: 'refresh', topic: 'weather_trigger' };
}

if (msg.topic === 'update_physics' && msg.payload && typeof msg.payload.enabled === 'boolean') {
    BMS.writeValue('physics_enabled', msg.payload.enabled);
    persistSettings();
