    return null;
}

return null;

const vp = global.get('virtualPoints') || {};
const city = vp['loc_city']?.value || 'Paris';
const country = vp['loc_country']?.value || 'France';
const lat = vp['loc_latitude']?.value || 48.8566;
const lon = vp['loc_longitude']?.value || 2.3522;

if (city && city.trim()) {
    msg.location = { city: city, country: country };
    node.status({fill: 'blue', shape: 'dot', text: city + ', ' + country});
} else {
    msg.location = { lat: lat, lon: lon };
    node.status({fill: 'blue', shape: 'dot', text: lat.toFixed(2) + ', ' + lon.toFixed(2)});
}
return msg;

const BMS = global.get('BMS');
const bacnet = global.get('bacnetPoints') || {};

if (!msg.payload) {
    node.status({fill: 'red', shape: 'ring', text: 'No data'});
    return null;
}

const weather = msg.payload;
const temp = weather.tempc;
if (temp !== undefined && bacnet['glob_outside_temp']) {
    bacnet['glob_outside_temp'].value = Math.round(temp * 10) / 10;
}

const clouds = weather.clouds || 0;
const now = new Date();
const nowUnix = Math.floor(now.getTime() / 1000);
const sunriseUnix = weather.sunrise;
const sunsetUnix = weather.sunset;
const isDaylight = sunriseUnix && sunsetUnix ? (nowUnix >= sunriseUnix && nowUnix <= sunsetUnix) : true;

let estimatedLux = isDaylight ? Math.round(50000 * (1 - (clouds / 100) * 0.9)) : 10;
if (bacnet['glob_outside_lux']) bacnet['glob_outside_lux'].value = estimatedLux;
global.set('bacnetPoints', bacnet);

// sun_* virtual points are owned exclusively by Calculate Sun (1 min tick) —
// writing them here too made the two sources fight every 10 minutes.

const tempStr = temp !== undefined ? temp.toFixed(1) + '°C' : '?';
const location = msg.location?.city || 'GPS';
node.status({fill: 'green', shape: 'dot', text: tempStr + ' | ' + estimatedLux + ' lux | ' + location});
msg.weatherUpdate = tempStr + ', ' + clouds + '% clouds, ' + estimatedLux + ' lux';
return msg;

const BMS = global.get('BMS');
const now = (BMS && BMS.now) ? BMS.now() : new Date();   // horloge système (cf. mode Démo/Test)
const h = now.getHours();
const m = now.getMinutes();
const d = now.getDay() === 0 ? 7 : now.getDay();
const minutesSinceMidnight = h * 60 + m;
const minuteOfWeek = (d - 1) * 1440 + minutesSinceMidnight;

if (BMS) {
    BMS.setVirtualValue('glob_time_hour', h);
    BMS.setVirtualValue('glob_time_day', d);
    BMS.setVirtualValue('glob_time_minutes', minutesSinceMidnight);
    BMS.setVirtualValue('glob_time_minute_of_week', minuteOfWeek);
    BMS.setVirtualValue('glob_time_epoch_min', Math.floor(now.getTime() / 60000));  // monotonic, wrap-safe for timers
}

node.status({fill: 'green', shape: 'dot', text: 'Day ' + d + ' ' + h + ':' + m.toString().padStart(2,'0') + ' (week min: ' + minuteOfWeek + ')'});
return msg;

const bacnetPoints = global.get('bacnetPoints') || {};
const bmsMetadata = global.get('bmsMetadata') || {};
const virtualPoints = global.get('virtualPoints') || {};

const devices = [];

Object.entries(bacnetPoints).forEach(([id, point]) => {
    const meta = bmsMetadata[id] || { tags: [], zone: '' };
    devices.push({
        id: id,
        name: point.objectName,
        type: point.access === 'read_only' ? 'sensor' : 'actuator',
        units: point.units,
        access: point.access,
        min: point.min,
        max: point.max,
        value: point.value,
        zone: meta.zone || '',
        tags: meta.tags || [],
        source: 'bacnet'
    });
});

Object.entries(virtualPoints).forEach(([id, point]) => {
    devices.push({
        id: id,
        name: point.name,
        type: 'virtual',
        units: point.units,
        access: point.writable ? 'read_write' : 'read_only',
        min: point.min,
        max: point.max,
        value: point.value,
        zone: '',
        tags: [],
        source: 'virtual'
    });
});

const allTags = new Set();
Object.values(bmsMetadata).forEach(m => {
    if (m.tags) m.tags.forEach(t => allTags.add(t));
});

msg.payload = {
    devices: devices,
    allTags: [...allTags].sort()
};

node.status({ fill: 'green', shape: 'dot', text: devices.length + ' devices, ' + allTags.size + ' tags' });
return msg;

const topic = msg.topic;
const payload = msg.payload;

if (!topic || !payload) return null;

let bmsMetadata = global.get('bmsMetadata') || {};

switch (topic) {
    case 'tag_add': {
        const { deviceId, tag } = payload;
        if (!bmsMetadata[deviceId]) bmsMetadata[deviceId] = { tags: [], zone: '' };
        if (!bmsMetadata[deviceId].tags) bmsMetadata[deviceId].tags = [];
        if (!bmsMetadata[deviceId].tags.includes(tag)) {
            bmsMetadata[deviceId].tags.push(tag);
            bmsMetadata[deviceId].tags.sort();
            node.warn(`Tag added: ${tag} → ${deviceId}`);
        }
        break;
    }
    case 'tag_remove': {
        const { deviceId, tag } = payload;
        if (bmsMetadata[deviceId] && bmsMetadata[deviceId].tags) {
            const idx = bmsMetadata[deviceId].tags.indexOf(tag);
            if (idx >= 0) { bmsMetadata[deviceId].tags.splice(idx, 1); node.warn(`Tag removed: ${tag} ← ${deviceId}`); }
        }
        break;
    }
    case 'tag_create': {
        node.warn(`Tag created: ${payload.tag}`);
        break;
    }
}

global.set('bmsMetadata', bmsMetadata);
try { global.set('bmsMetadata', bmsMetadata, 'file'); } catch (e) { /* file store not configured */ }
node.status({ fill: 'green', shape: 'dot', text: topic + ' processed' });
return null;

// Optional auth: if BMS_API_TOKEN env var is set on the Node-RED process,
// require it in the x-bms-token header (endpoints are otherwise open like the dashboard)
const required = env.get('BMS_API_TOKEN');
if (required && (!msg.req || msg.req.headers['x-bms-token'] !== required)) {
    msg.statusCode = 401;
    msg.payload = { error: 'unauthorized' };
    return msg;
}

const bacnetPoints = global.get('bacnetPoints') || {};
const bmsMetadata = global.get('bmsMetadata') || {};
const virtualPoints = global.get('virtualPoints') || {};

const sensors = {}, actuators = {}, weather = {};
Object.entries(bacnetPoints).forEach(([id, p]) => {
    const meta = bmsMetadata[id] || {};
    const entry = { name: p.objectName, value: p.value, units: p.units, tags: meta.tags || [], zone: meta.zone || null };
    if (p.min !== undefined) entry.min = p.min;
    if (p.max !== undefined) entry.max = p.max;
    if (id.startsWith('glob_outside')) weather[id] = entry;
    else if (p.access === 'read_only') sensors[id] = entry;
    else actuators[id] = entry;
});

const virtuals = {};
Object.entries(virtualPoints).forEach(([id, p]) => {
    virtuals[id] = { name: p.name, value: p.value, units: p.units, writable: !!p.writable };
    if (p.min !== undefined) virtuals[id].min = p.min;
    if (p.max !== undefined) virtuals[id].max = p.max;
});

const tags = {};
Object.values(bmsMetadata).forEach(m => (m.tags || []).forEach(t => { tags[t] = (tags[t] || 0) + 1; }));

msg.payload = {
    points: { sensors: sensors, actuators: actuators, weather: weather },
    virtualPoints: virtuals,
    tags: tags,
    config: {
        behavior_agents: global.get('behaviorAgents') || [],
        defined_states: global.get('stateRegistry') || [],
        rule_groups: global.get('ruleGroups') || [],
        dashboard: global.get('dashboardConfig') || { widgets: [] }
    }
};
return msg;

// Optional auth: if BMS_API_TOKEN env var is set on the Node-RED process,
// require it in the x-bms-token header (endpoints are otherwise open like the dashboard)
const required = env.get('BMS_API_TOKEN');
if (required && (!msg.req || msg.req.headers['x-bms-token'] !== required)) {
    msg.statusCode = 401;
    msg.payload = { error: 'unauthorized' };
    return msg;
}

const BMS = global.get('BMS');
if (!BMS || !BMS.applyConfig) { msg.statusCode = 503; msg.payload = { error: 'BMS not initialized' }; return msg; }

let cfg = msg.payload;
if (typeof cfg === 'string') {
    try { cfg = JSON.parse(cfg); }
    catch (e) { msg.statusCode = 400; msg.payload = { error: 'invalid JSON: ' + e.message }; return msg; }
}

const result = BMS.applyConfig(cfg);
msg.statusCode = result.errors.length > 0 ? 400 : 200;
msg.payload = result;
node.status({ fill: result.errors.length > 0 ? 'red' : 'green', shape: 'dot', text: 'applied: ' + (result.applied.join(', ') || 'nothing') });
return msg;

// Optional auth: if BMS_API_TOKEN env var is set on the Node-RED process,
// require it in the x-bms-token header (endpoints are otherwise open like the dashboard)
const required = env.get('BMS_API_TOKEN');
if (required && (!msg.req || msg.req.headers['x-bms-token'] !== required)) {
    msg.statusCode = 401;
    msg.payload = { error: 'unauthorized' };
    return msg;
}

const groups = global.get('ruleGroups') || [];
const agents = global.get('behaviorAgents') || [];
const fireLog = global.get('ruleFireLog') || {};
const vp = global.get('virtualPoints') || {};

msg.payload = {
    rulesLoaded: groups.reduce((s, g) => s + ((g.enabled !== false && g.rules) ? g.rules.length : 0), 0),
    groups: groups.map(g => ({ id: g.id, name: g.name, enabled: g.enabled !== false, rules: (g.rules || []).map(r => r.name) })),
    agents: agents.map(a => ({ id: a.id, name: a.name, enabled: a.enabled, rule_group: a.rule_group })),
    fireLog: fireLog,
    physics_enabled: vp.physics_enabled ? vp.physics_enabled.value : null,
    serverTime: new Date().toISOString()
};
return msg;

// Optional auth: if BMS_API_TOKEN env var is set on the Node-RED process,
// require it in the x-bms-token header (endpoints are otherwise open like the dashboard)
const required = env.get('BMS_API_TOKEN');
if (required && (!msg.req || msg.req.headers['x-bms-token'] !== required)) {
    msg.statusCode = 401;
    msg.payload = { error: 'unauthorized' };
    return msg;
}

const BMS = global.get('BMS');
const bmsMetadata = global.get('bmsMetadata') || {};
const values = BMS ? BMS.getValues() : {};

// include soft states so the full fact universe is visible
const cache = global.get('myStateCache');
const states = global.get('stateRegistry') || [];
// Le cache d'états n'est créé qu'au premier set_state (State Manager). Sans repli
// sur la valeur par défaut, /bms/points masque les 37 états jusqu'à la première
// écriture : vue tronquée pour l'API comme pour l'assistant IA. Même repli que Build Facts.
states.forEach(s => { const v = cache ? cache.get(s.id) : undefined; values[s.id] = (v !== undefined) ? v : s.defaultValue; });

const q = (msg.req && msg.req.query) || {};
if (q.id) {
    if (values[q.id] === undefined) { msg.statusCode = 404; msg.payload = { error: 'unknown point: ' + q.id }; return msg; }
    msg.payload = { id: q.id, value: values[q.id], metadata: bmsMetadata[q.id] || null };
    return msg;
}
if (q.tag) {
    const out = {};
    Object.entries(bmsMetadata).forEach(([id, m]) => { if ((m.tags || []).includes(q.tag)) out[id] = values[id]; });
    msg.payload = out;
    return msg;
}
msg.payload = values;
return msg;

// Optional auth: if BMS_API_TOKEN env var is set on the Node-RED process,
// require it in the x-bms-token header (endpoints are otherwise open like the dashboard)
const required = env.get('BMS_API_TOKEN');
if (required && (!msg.req || msg.req.headers['x-bms-token'] !== required)) {
    msg.statusCode = 401;
    msg.payload = { error: 'unauthorized' };
    return msg;
}

const BMS = global.get('BMS');
const p = msg.payload || {};
if (!p.id || p.value === undefined) { msg.statusCode = 400; msg.payload = { error: 'body must be {id, value, simulate?}' }; return msg; }

if (p.simulate === true) {
    // hardware override: writes the raw point like the Hardware Simulator page (it IS the simulated hardware)
    const bacnet = global.get('bacnetPoints') || {};
    if (!bacnet[p.id]) { msg.statusCode = 404; msg.payload = { error: 'unknown bacnet point: ' + p.id }; return msg; }
    bacnet[p.id].value = p.value;
    global.set('bacnetPoints', bacnet);
    msg.payload = { ok: true, mode: 'simulate', id: p.id, value: p.value };
    return msg;
}

if (!BMS) { msg.statusCode = 503; msg.payload = { error: 'BMS not initialized' }; return msg; }

// Voie asynchrone : en mode BACnet une écriture est une requête réseau, et la
// voie synchrone la refuse (à raison — elle ne peut pas la confirmer dans le
// tick courant). Les droits et les bornes sont appliqués par la couche BMS.
return BMS.writeValueAsync(p.id, p.value, { source: 'api' }).then(res => {
    if (!res || !res.ok) {
        msg.statusCode = 403;
        msg.payload = { error: (res && res.error) || ('write refused: ' + p.id) };
        return msg;
    }
    msg.payload = { ok: true, mode: 'bms', id: p.id, value: BMS.getValue(p.id) };
    return msg;
});

// Optional auth: if BMS_API_TOKEN env var is set, require it in x-bms-token
const required = env.get('BMS_API_TOKEN');
if (required && (!msg.req || msg.req.headers['x-bms-token'] !== required)) {
    msg.statusCode = 401;
    msg.payload = { error: 'unauthorized' };
    return msg;
}

// Rolling runtime log captured by the custom logger in settings.js (warn/error/info
// from all nodes). Query: ?n=200 (tail count), ?level=warn|error, ?grep=regex.
const buf = global.get('sysLogBuffer') || [];
const q = (msg.req && msg.req.query) || {};
let out = buf.slice();

if (q.level) {
    const order = { fatal: 10, error: 20, warn: 30, info: 40, debug: 50, trace: 60 };
    const max = order[String(q.level).toLowerCase()] || 60;
    out = out.filter(e => (order[e.lvl] || 60) <= max);
}
if (q.grep) {
    let re; try { re = new RegExp(q.grep, 'i'); } catch (e) { re = null; }
    if (re) out = out.filter(e => re.test(e.msg || '') || re.test(e.name || '') || re.test(e.type || ''));
}
const n = q.n ? Math.max(1, Math.min(Number(q.n), out.length)) : 200;
out = out.slice(-n);

msg.payload = { total: buf.length, returned: out.length, entries: out };
msg.statusCode = 200;
return msg;

// POST /bms/chat control. Starts a DETACHED background turn (Chat Turn Runner) and returns
// immediately, so a long multi-pass turn never hits the client request timeout. The reply is
// observed by the client polling GET /bms/chattranscript.
// outputs: [0]=Chat Turn Runner (start), [1]=HTTP ack response
const action = (msg.payload || {}).action;
function ack(obj, code) { msg.statusCode = code || 200; msg.payload = obj; return [null, msg]; }

if (action === 'reset_chat') {
    flow.set('chatHistory', []); flow.set('chatTranscript', []);
    flow.set('chatPending', false); flow.set('chatCancel', false); flow.set('chatRetry', null);
    global.set('aiApiLog', []);
    return ack({ ok: true, reset: true });
}
if (action === 'clear_log') { global.set('aiApiLog', []); return ack({ ok: true, cleared: true }); }
if (action === 'cancel_chat') { flow.set('chatCancel', true); flow.set('chatPending', false); flow.set('chatRetry', null); return ack({ ok: true, cancelled: true }); }
if (action !== 'user_message' || !(msg.payload && msg.payload.text)) return ack({ ok: false, error: 'action must be user_message | reset_chat | clear_log | cancel_chat' }, 400);

const settings = global.get('aiChatSettings') || {};
const provider = settings.provider || 'anthropic';
const providers = global.get('aiProviders') || {};
if (!(settings.keys && settings.keys[provider])) return ack({ ok: false, error: 'No API key for ' + ((providers[provider] || {}).label || provider) + ' — set it via the gear icon.' });
if (flow.get('chatPending')) return ack({ ok: false, error: 'A turn is already running — wait for it or press Cancel.' });

const text = String(msg.payload.text);
const t = flow.get('chatTranscript') || [];
t.push({ role: 'user', text: text });
flow.set('chatTranscript', t);
flow.set('chatPending', true);
flow.set('chatCancel', false);

msg.statusCode = 200; msg.payload = { ok: true, started: true };
return [{ payload: { text: text } }, msg];   // out0 -> runner (detached), out1 -> http ack

// Optional auth: if BMS_API_TOKEN env var is set, require it in x-bms-token
const required = env.get('BMS_API_TOKEN');
if (required && (!msg.req || msg.req.headers['x-bms-token'] !== required)) {
    msg.statusCode = 401; msg.payload = { error: 'unauthorized' };
    return msg;
}
// Read the structured API call log (aiApiLog). Polled by the API Log UI (server->widget
// push is unreliable in this Dashboard version, so the panel pulls).
const buf = global.get('aiApiLog') || [];
const q = (msg.req && msg.req.query) || {};
const n = q.n ? Math.max(1, Math.min(Number(q.n), buf.length)) : 500;
msg.statusCode = 200;
msg.payload = { total: buf.length, entries: buf.slice(-n) };
return msg;

// GET /bms/chatsettings -> read; POST /bms/chatsettings -> save/erase. Fetch-driven settings
// panel (server->widget push is unreliable here). Returns {provider, keys, models, reasoning, keySet}.
const required = env.get('BMS_API_TOKEN');
if (required && (!msg.req || msg.req.headers['x-bms-token'] !== required)) { msg.statusCode = 401; msg.payload = { error: 'unauthorized' }; return msg; }

const PROVIDERS = ['anthropic', 'openai', 'deepseek', 'mistral'];
function persist(s) { global.set('aiChatSettings', s); try { global.set('aiChatSettings', s, 'file'); } catch (e) {} }

let s = global.get('aiChatSettings') || {};
if (!s.keys) s = { provider: 'anthropic', keys: { anthropic: '', openai: '', deepseek: '', mistral: '' }, models: { anthropic: 'claude-sonnet-4-6', openai: 'gpt-5.1', deepseek: 'deepseek-v4-flash', mistral: 'mistral-large-latest' }, reasoning: 'off' };
if (s.reasoning === undefined) s.reasoning = 'off';
if (s.keys && s.keys.mistral === undefined) s.keys.mistral = '';
if (s.models && !s.models.mistral) s.models.mistral = 'mistral-large-latest';

const method = (msg.req && msg.req.method) || 'GET';
if (method === 'POST') {
    const p = msg.payload || {};
    if (p.provider && PROVIDERS.indexOf(p.provider) !== -1) s.provider = p.provider;
    if (p.keys) PROVIDERS.forEach(k => { if (typeof p.keys[k] === 'string') s.keys[k] = p.keys[k].trim(); });
    if (p.models) PROVIDERS.forEach(k => { if (p.models[k]) s.models[k] = String(p.models[k]).trim(); });
    if (typeof p.reasoning === 'string') s.reasoning = p.reasoning;
    if (p.eraseAllKeys === true) PROVIDERS.forEach(k => s.keys[k] = '');
    if (p.eraseKey && s.keys[p.eraseKey] !== undefined) s.keys[p.eraseKey] = '';
    persist(s);
}

const keySet = {}; PROVIDERS.forEach(k => keySet[k] = !!s.keys[k]);
const active = !!s.keys[s.provider];
node.status({ fill: active ? 'green' : 'grey', shape: 'dot',
    text: (active ? s.provider + '/' + (s.models[s.provider] || '?') : s.provider + ': no key') + (s.reasoning && s.reasoning !== 'off' ? ' [' + s.reasoning + ']' : '') });
msg.statusCode = 200;
msg.payload = { provider: s.provider, keys: s.keys, models: s.models, reasoning: s.reasoning || 'off', keySet: keySet };
return msg;

// Chat Turn Runner: runs the full turn (provider + tool loop) in the background, writing to the
// server-side transcript (flow.chatTranscript) and clearing flow.chatPending when done. Triggered
// by a message (not an HTTP request), so it has NO response timeout — long multi-pass turns are fine.
const settings = global.get('aiChatSettings') || {};
const providers = global.get('aiProviders') || {};
const provider = settings.provider || 'anthropic';
const style = (providers[provider] || {}).style || 'anthropic';
const fetchFn = global.get('fetchFn');
const aiLog = global.get('aiLog') || function () {};
const trim = global.get('aiLogTrim') || function (x) { return x; };
const model = (settings.models && settings.models[provider]) || '?';
const maxTok = (providers[provider] || {}).maxTokens || '?';
const BMS = global.get('BMS');
const text = (msg.payload && msg.payload.text) || '';

function pushT(m) { const t = flow.get('chatTranscript') || []; t.push(m); if (t.length > 300) t.shift(); flow.set('chatTranscript', t); }

if (!fetchFn) { pushT({ role: 'error', text: 'fetchFn not available — check settings.js.' }); flow.set('chatPending', false); return null; }

return (async function () {
    let finalReached = false;
    try {
        let history = flow.get('chatHistory') || [];
        if (flow.get('chatHistoryV') !== 3) { history = []; flow.set('chatHistoryV', 3); }
        history.push({ role: 'user', text: text });
        if (history.length > 40) history = history.slice(-40);

        // Read the provider's own retry hint, if any. Retry-After may be delta-seconds OR an
        // HTTP-date; some APIs use retry-after-ms or x-ratelimit-reset(-tokens). Returns seconds or null.
        const retryHint = function (resp) {
            try {
                const h = resp.headers; if (!h || !h.get) return null;
                const ms = h.get('retry-after-ms') || h.get('x-ratelimit-reset-after-ms');
                if (ms && !isNaN(+ms)) return Math.max(1, Math.ceil(+ms / 1000));
                const ra = h.get('retry-after');
                if (ra) {
                    if (!isNaN(+ra)) return Math.max(1, parseInt(ra, 10));            // delta-seconds
                    const t = Date.parse(ra); if (!isNaN(t)) return Math.max(1, Math.ceil((t - Date.now()) / 1000)); // HTTP-date
                }
                const rs = h.get('x-ratelimit-reset') || h.get('ratelimit-reset');
                if (rs && !isNaN(+rs)) { const n = +rs; return n > 1e6 ? Math.max(1, Math.ceil(n - Date.now() / 1000)) : Math.max(1, Math.ceil(n)); }
            } catch (e) {}
            return null;
        };
        const MAXTRY = 6;
        // Call the provider with backoff on 429 (rate limit) / 5xx. The turn is detached (no client
        // timeout), so we can wait out the rate-limit window and continue rather than failing.
        // chatRetry stays set across the wait (cleared only on a usable response / cancel / give-up)
        // so the UI banner counts down smoothly instead of flickering.
        const callProvider = async function (req) {
            for (let attempt = 0; attempt < MAXTRY; attempt++) {
                if (flow.get('chatCancel')) { flow.set('chatRetry', null); return null; }
                const resp = await fetchFn(req.url, { method: 'POST', headers: req.headers, body: JSON.stringify(req.payload) });
                if (resp.status !== 429 && resp.status < 500) { flow.set('chatRetry', null); return resp; }
                const hint = retryHint(resp);
                let wait, source;
                if (hint != null) { wait = Math.min(300, hint); source = 'api'; }       // trust the provider's hint
                else { wait = Math.min(90, 10 * Math.pow(2, attempt)); source = 'backoff'; }  // 10,20,40,80,90,90 — not optimistic
                aiLog('info', '⏳ HTTP ' + resp.status + ' from ' + provider + ' — ' + (source === 'api' ? 'provider asked to wait ' : 'backing off ') + wait + 's (attempt ' + (attempt + 1) + '/' + MAXTRY + ', source=' + source + ')');
                flow.set('chatRetry', { until: Date.now() + wait * 1000, seconds0: wait, status: resp.status, provider: provider, attempt: attempt + 1, max: MAXTRY, source: source });
                await new Promise(function (r) { setTimeout(r, wait * 1000); });
            }
            flow.set('chatRetry', null);
            return null;   // exhausted retries
        };

        for (let round = 0; round < 10; round++) {
            if (flow.get('chatCancel')) { pushT({ role: 'error', text: '(cancelled)' }); finalReached = true; break; }
            const req = global.get('aiBuildRequest')(history, settings);
            aiLog('request', '→ REQUEST ' + provider + '/' + model + ' (' + history.length + ' msgs)', { url: req.url, body: trim(req.payload) });
            const resp = await callProvider(req);
            if (!resp) { pushT({ role: 'error', text: flow.get('chatCancel') ? '(cancelled)' : ('Rate limit / server errors from ' + provider + ' persisted after retries — try again shortly, switch provider, or upgrade the API tier.') }); finalReached = true; break; }
            let body; try { body = await resp.json(); } catch (e) { body = null; }
            const parsed = global.get('aiParseResponse')(style, resp.status, body);

            if (!parsed.ok) { aiLog('error', '← ERROR ' + resp.status + ': ' + parsed.error, { statusCode: resp.status, body: body }); pushT({ role: 'error', text: parsed.error }); finalReached = true; break; }
            if (parsed.truncated) {
                const wasTool = parsed.toolCalls.length > 0;
                const advice = 'Apply the configuration in smaller parts (merge:true), or raise the provider max_tokens.';
                aiLog('error', '← TRUNCATED ' + provider + ' (max_tokens=' + maxTok + ')' + (wasTool ? ' [tool call discarded]' : ''), { body: body });
                pushT({ role: 'error', text: '⚠ ' + (wasTool ? 'Configuration truncated and NOT applied. ' : 'Reply cut off. ') + advice });
                finalReached = true; break;
            }
            if (parsed.stop === 'tool' && parsed.toolCalls.length) {
                history.push({ role: 'assistant', text: parsed.text, toolCalls: parsed.toolCalls, reasoning: parsed.reasoning });
                if (parsed.text) pushT({ role: 'assistant', text: parsed.text });
                const results = [];
                parsed.toolCalls.forEach(function (tc) {
                    if (tc.name === 'read_config') {
                        const sec = (tc.input && tc.input.section) || '';
                        let slice;
                        if (sec === 'rule_groups') {
                            const gs = global.get('ruleGroups') || [];
                            slice = (tc.input && tc.input.id) ? { rule_group: gs.filter(function (g) { return g.id === tc.input.id; })[0] || null } : { rule_groups: gs };
                        } else if (sec === 'defined_states') slice = { defined_states: global.get('stateRegistry') || [] };
                        else if (sec === 'behavior_agents') slice = { behavior_agents: global.get('behaviorAgents') || [] };
                        else if (sec === 'dashboard') slice = { dashboard: global.get('dashboardConfig') || { widgets: [] } };
                        else slice = { error: 'unknown section: ' + sec };
                        results.push({ id: tc.id, name: tc.name, content: JSON.stringify(slice) });
                        pushT({ role: 'tool', text: '🔎 read ' + sec + (tc.input && tc.input.id ? ' (' + tc.input.id + ')' : ''), ok: true });
                        aiLog('tool', '🔎 read_config ' + sec + (tc.input && tc.input.id ? ' ' + tc.input.id : ''), { input: tc.input });
                        return;
                    }
                    let result = (tc.name === 'apply_bms_config' && BMS && BMS.applyConfig) ? BMS.applyConfig(tc.input) : { errors: ['unknown tool: ' + tc.name] };
                    results.push({ id: tc.id, name: tc.name, content: JSON.stringify(result) });
                    const ok = !(result.errors || []).length, clean = ok && !(result.unknownFacts || []).length;
                    const summary = ok
                        ? '✓ Configuration applied: ' + Object.entries(result.counts || {}).map(function (kv) { return kv[1] + ' ' + kv[0]; }).join(', ')
                          + ((result.unknownFacts || []).length ? ' — ⚠ unknown facts: ' + result.unknownFacts.join(', ') : '')
                        : '✗ Apply failed: ' + result.errors.join('; ');
                    pushT({ role: 'tool', text: summary, ok: clean });
                    aiLog('tool', '⚙ ' + summary, { input: tc.input, result: result });
                });
                history.push({ role: 'tool', results: results });
                flow.set('chatHistory', history);
                continue;
            }
            history.push({ role: 'assistant', text: parsed.text || '(empty response)', reasoning: parsed.reasoning });
            flow.set('chatHistory', history);
            const u = parsed.usage || {};
            aiLog('response', '← 200 ' + provider + ' stop=end tokens=' + u.in + '/' + u.out + (u.cacheRead ? ' (cached in=' + u.cacheRead + ')' : ''), { stop: 'end', text: parsed.text, body: body });
            pushT({ role: 'assistant', text: parsed.text || '(empty response)' });
            finalReached = true; break;
        }
        if (!finalReached) pushT({ role: 'error', text: '(stopped after 10 tool rounds — ask me to continue)' });
    } catch (e) {
        aiLog('error', '✗ TURN ERROR: ' + e, { error: String(e) });
        pushT({ role: 'error', text: 'Request failed: ' + e });
    } finally {
        flow.set('chatPending', false);
        flow.set('chatRetry', null);
    }
})();

const required = env.get('BMS_API_TOKEN');
if (required && (!msg.req || msg.req.headers['x-bms-token'] !== required)) { msg.statusCode = 401; msg.payload = { error: 'unauthorized' }; return msg; }
// Server-side display transcript + pending flag, polled by the chat widget (restores the
// conversation after navigation and surfaces a long turn's result without a held connection).
const rt = flow.get('chatRetry');
msg.statusCode = 200;
msg.payload = {
    messages: flow.get('chatTranscript') || [],
    pending: !!flow.get('chatPending'),
    retry: rt ? { seconds: Math.max(0, Math.ceil((rt.until - Date.now()) / 1000)), status: rt.status, provider: rt.provider, attempt: rt.attempt, max: rt.max, source: rt.source } : null
};
return msg;

// Optional auth: if BMS_API_TOKEN env var is set on the Node-RED process,
// require it in the x-bms-token header (endpoints are otherwise open like the dashboard)
const required = env.get('BMS_API_TOKEN');
if (required && (!msg.req || msg.req.headers['x-bms-token'] !== required)) {
    msg.statusCode = 401;
    msg.payload = { error: 'unauthorized' };
    return msg;
}

const BMS = global.get('BMS');
const ALLOWED = [1, 2, 5, 10, 30, 60, 120];

function currentState() {
    const c = global.get('demoClock') || { multiplier: 1 };
    const multiplier = c.multiplier || 1;
    const virtual = (BMS && BMS.now) ? BMS.now() : new Date();

    // Rend concret l'effet du réglage : la temporisation d'inoccupation est la
    // constante qui rend une démonstration en direct impraticable à 1×.
    const states = global.get('stateRegistry') || [];
    const cache = global.get('myStateCache');
    const def = states.find(s => s.id === 'st_timeout_office');
    let timeoutMinutes = null;
    if (def) {
        const live = cache ? cache.get('st_timeout_office') : undefined;
        timeoutMinutes = (live !== undefined) ? live : def.defaultValue;
    }

    return {
        multiplier: multiplier,
        accelerated: multiplier !== 1,
        allowed: ALLOWED,
        virtualTime: virtual.toISOString(),
        realTime: new Date().toISOString(),
        occupancyTimeoutMinutes: timeoutMinutes,
        occupancyTimeoutRealSeconds: (timeoutMinutes === null) ? null : Math.round(timeoutMinutes * 60 / multiplier)
    };
}

const method = ((msg.req && msg.req.method) || 'GET').toUpperCase();
if (method === 'GET') {
    msg.payload = currentState();
    return msg;
}

const requested = Number((msg.payload || {}).multiplier);
if (!ALLOWED.includes(requested)) {
    msg.statusCode = 400;
    msg.payload = { error: 'multiplier must be one of ' + ALLOWED.join(', '), received: (msg.payload || {}).multiplier };
    return msg;
}

// Ré-ancrage : l'heure virtuelle courante devient la nouvelle origine, sinon
// changer de vitesse ferait sauter l'horloge en avant ou en arrière.
const virtualNow = ((BMS && BMS.now) ? BMS.now() : new Date()).getTime();
global.set('demoClock', { multiplier: requested, anchorReal: Date.now(), anchorVirtual: virtualNow });
try { global.set('demoClockMultiplier', requested, 'file'); } catch (e) { /* file store not configured */ }

node.warn('⏩ Demo/Test mode : multiplicateur de temps réglé sur ×' + requested);
msg.payload = currentState();
return msg;

// Optional auth: if BMS_API_TOKEN env var is set on the Node-RED process,
// require it in the x-bms-token header (endpoints are otherwise open like the dashboard)
const required = env.get('BMS_API_TOKEN');
if (required && (!msg.req || msg.req.headers['x-bms-token'] !== required)) {
    msg.statusCode = 401;
    msg.payload = { error: 'unauthorized' };
    return msg;
}

const safety = global.get('bmsSafety');
if (!safety) {
    msg.statusCode = 503;
    msg.payload = { error: 'safety layer not initialised' };
    return msg;
}

const q = (msg.req && msg.req.query) || {};
let entries = safety.log();

if (q.id) entries = entries.filter(e => e.id === q.id);
if (q.source) entries = entries.filter(e => e.source === q.source);
if (q.failed === 'true') entries = entries.filter(e => !e.ok);

const n = q.n ? parseInt(q.n, 10) : 100;
entries = entries.slice(-Math.max(1, n));

msg.payload = {
    count: entries.length,
    rateLimit: global.get('writeRateLimit') || null,
    requireApprovalForRealPoints: global.get('requireApprovalForRealPoints') !== false,
    entries: entries.map(e => ({
        time: new Date(e.ts).toISOString(),
        id: e.id, value: e.value, source: e.source, ok: e.ok, error: e.error
    }))
};
return msg;

// Optional auth: if BMS_API_TOKEN env var is set on the Node-RED process,
// require it in the x-bms-token header (endpoints are otherwise open like the dashboard)
const required = env.get('BMS_API_TOKEN');
if (required && (!msg.req || msg.req.headers['x-bms-token'] !== required)) {
    msg.statusCode = 401;
    msg.payload = { error: 'unauthorized' };
    return msg;
}

const core = global.get('bmsCore');
const io = global.get('ioDrivers');
if (!core || !io) {
    msg.statusCode = 503;
    msg.payload = { error: 'BMS not initialised' };
    return msg;
}

const SIM_DEFAULTS = { host: '127.0.0.1', port: 47810, deviceId: 1234, controlPort: 47811 };

function state() {
    const mode = global.get('bacnetMode') || 'disconnected';
    const target = global.get('bacnetTarget') || null;
    const driver = io.driverOrNull ? io.driverOrNull('bacnet') : null;
    const bacnetPoints = global.get('bacnetPoints') || {};
    return {
        mode: mode,                       // 'disconnected' | 'simulated' | 'real'
        target: target,
        simDefaults: SIM_DEFAULTS,
        driver: driver ? driver.status() : { connected: false },
        pointCount: Object.keys(bacnetPoints).length
    };
}

const method = ((msg.req && msg.req.method) || 'GET').toUpperCase();
const q = (msg.req && msg.req.query) || {};

if (method === 'GET') {
    if (q.browse === 'true') {
        const driver = io.driverOrNull && io.driverOrNull('bacnet');
        if (!driver || !driver.status().connected) {
            msg.statusCode = 409;
            msg.payload = { error: 'aucun serveur BACnet connecté' };
            return msg;
        }
        // Parcours à la demande : renvoie les objets du device et leur liaison.
        return driver.browse().then(objects => {
            const boundNames = new Set([...driver.bindings.keys()]);
            msg.payload = {
                deviceId: driver.status().deviceId,
                count: objects.length,
                objects: objects.map(o => ({
                    type: o.type, instance: o.instance, name: o.name,
                    description: o.description, writable: o.writable,
                    boundTo: boundNames.has(o.name) ? o.name : null
                }))
            };
            return msg;
        }).catch(e => {
            msg.statusCode = 502;
            msg.payload = { error: 'parcours impossible : ' + e.message };
            return msg;
        });
    }
    msg.payload = state();
    return msg;
}

// POST — changement de mode / connexion
const body = msg.payload || {};
const mode = body.mode;
if (!['disconnected', 'simulated', 'real'].includes(mode)) {
    msg.statusCode = 400;
    msg.payload = { error: "mode must be 'simulated', 'real' or 'disconnected'" };
    return msg;
}

const previous = io.driverOrNull && io.driverOrNull('bacnet');
if (previous) { try { previous.disconnect(); } catch (e) { /* déjà fermé */ } }

if (mode === 'disconnected') {
    global.set('bacnetMode', 'disconnected');
    global.set('defaultDriver', 'simulator');
    global.set('bacnetTarget', null);
    try { global.set('bacnetMode', 'disconnected', 'file'); } catch (e) {}
    node.warn('Source de points déconnectée — les valeurs sont figées.');
    msg.payload = state();
    return msg;
}

const target = (mode === 'simulated')
    ? Object.assign({}, SIM_DEFAULTS, { host: body.host || SIM_DEFAULTS.host })
    : { host: body.host, port: Number(body.port) || 47808, deviceId: (body.deviceId === undefined || body.deviceId === null || body.deviceId === '') ? null : Number(body.deviceId) };

if (!target.host) {
    msg.statusCode = 400;
    msg.payload = { error: "l'adresse du serveur BACnet est requise (IP ou nom d'hôte)" };
    return msg;
}

let driver;
try {
    driver = core.createBacnetDriver({ global: global, node: node }, {
        host: target.host, port: target.port, deviceId: target.deviceId,
        clientPort: Number(body.clientPort) || 47809,
        interface: body.interface || '0.0.0.0'
    });
} catch (e) {
    msg.statusCode = 500;
    msg.payload = { error: e.message };
    return msg;
}

return driver.connect().then(result => {
    io.register('bacnet', driver);
    global.set('defaultDriver', 'bacnet');
    global.set('bacnetMode', mode);
    global.set('bacnetTarget', target);
    try {
        global.set('bacnetMode', mode, 'file');
        global.set('bacnetTarget', target, 'file');
    } catch (e) { /* file store not configured */ }
    node.warn('Mode BACnet : ' + mode + ' — ' + target.host + ':' + target.port +
              ' · ' + result.bound + ' points liés, ' + result.cov.ok + ' souscriptions COV');
    msg.payload = Object.assign(state(), { connectResult: result });
    return msg;
}).catch(e => {
    try { driver.disconnect(); } catch (err) {}
    msg.statusCode = 502;
    msg.payload = { error: 'connexion impossible : ' + e.message, target: target };
    return msg;
});

// Au démarrage, tenter le serveur BACnet simulé.
//
// Sans le mode « internal », un système fraîchement installé n'a aucune source
// de points : le bâtiment paraît figé, sans explication. On réutilise le MÊME
// chemin que l'interface (POST /bms/bacnet) plutôt que de dupliquer la logique
// de connexion — un seul endroit où elle peut se tromper.
//
// Si un mode a été mémorisé au dernier arrêt, on le respecte.

// Ne jamais écraser une connexion déjà établie : l'utilisateur (ou un test)
// a pu se connecter avant l'échéance de ce déclencheur.
const io = global.get('ioDrivers');
const existing = io && io.driverOrNull && io.driverOrNull('bacnet');
if (existing && existing.status().connected) {
    node.status({ fill: 'green', shape: 'dot', text: 'déjà connecté' });
    return null;
}

const remembered = global.get('bacnetMode');
if (remembered === 'disconnected') {
    node.status({ fill: 'grey', shape: 'ring', text: 'déconnecté (mémorisé)' });
    return null;
}

const target = global.get('bacnetTarget') || {};
const body = (remembered === 'real' && target.host)
    ? { mode: 'real', host: target.host, port: target.port, deviceId: target.deviceId }
    : { mode: 'simulated' };

const fetchFn = global.get('fetchFn');
const port = env.get('PORT') || 1880;

fetchFn('http://127.0.0.1:' + port + '/bms/bacnet', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body)
}).then(r => r.json().then(b => ({ ok: r.ok, b })))
  .then(({ ok, b }) => {
      if (ok) {
          node.status({ fill: 'green', shape: 'dot', text: b.mode + ' · ' + b.driver.bound + ' points' });
      } else {
          node.status({ fill: 'yellow', shape: 'ring', text: 'connexion impossible' });
          node.warn('Serveur BACnet injoignable au démarrage (' + (b.error || '') + '). ' +
                    'Lancez « bms-sim-start », puis connectez depuis la page BACnet Server.');
      }
  })
  .catch(e => {
      node.status({ fill: 'yellow', shape: 'ring', text: 'connexion impossible' });
      node.warn('Connexion BACnet au démarrage impossible : ' + e.message);
  });

return null;

// Optional auth: if BMS_API_TOKEN env var is set on the Node-RED process,
// require it in the x-bms-token header (endpoints are otherwise open like the dashboard)
const required = env.get('BMS_API_TOKEN');
if (required && (!msg.req || msg.req.headers['x-bms-token'] !== required)) {
    msg.statusCode = 401;
    msg.payload = { error: 'unauthorized' };
    return msg;
}

const cov = global.get('covPolicy');
const io = global.get('ioDrivers');
if (!cov) {
    msg.statusCode = 503;
    msg.payload = { error: 'BMS not initialised' };
    return msg;
}

const driver = (io && io.driverOrNull) ? io.driverOrNull('bacnet') : null;
const live = driver && driver.status().connected;

/**
 * État complet : profils, règles d'affectation, et pour chaque point
 * l'incrément EFFECTIF avec sa provenance. Sans la provenance, personne ne peut
 * expliquer pourquoi un point se comporte autrement que son voisin.
 */
function state() {
    const rates = live ? driver.rates() : {};
    const effective = cov.resolveAll();
    const out = {};
    for (const [id, r] of Object.entries(effective)) {
        out[id] = {
            unit: r.unit,
            increment: r.increment,
            minIntervalMs: r.minIntervalMs,
            heartbeatMs: r.heartbeatMs,
            source: r.source,
            profile: r.profile,
            // Incrément réellement posé dans l'appareil. Différent de
            // l'effectif = le réglage n'a pas encore été poussé, ou l'appareil
            // l'a refusé : dans les deux cas la bande morte est celle de
            // l'appareil, pas celle du BMS.
            applied: live ? driver.appliedIncrement(id) : null,
            notifPerMin: rates[id] === undefined ? null : rates[id]
        };
    }
    // Étiquettes connues, pour la liste d'affectation : moins cher que de faire
    // charger /bms/context (points + configuration complète) au widget.
    const tags = new Set();
    Object.values(global.get('bmsMetadata') || {}).forEach(m => (m.tags || []).forEach(t => tags.add(t)));

    return {
        profiles: cov.profiles(),
        assignments: cov.assignments(),
        overrides: cov.overrides(),
        unitDefaults: cov.UNIT_DEFAULTS,
        units: cov.UNITS,
        defaultProfileName: cov.DEFAULT_PROFILE_NAME,
        knownTags: [...tags].sort(),
        connected: !!live,
        // Ce que l'appareil annonce savoir faire. `covIncrementSettable` est la
        // seule chose que l'interface doit regarder pour décider d'afficher ou
        // de masquer les réglages d'incrément.
        capabilities: live ? driver.capabilities() : {
            subscribeCovProperty: false, subscribeCovPropertyMultiple: false,
            covIncrementSettable: false, reason: 'aucun serveur BACnet connecté'
        },
        rateWindowMin: 60,
        points: out
    };
}

/** Repousse les incréments vers l'appareil après toute édition. */
function pushAndRespond(extra) {
    if (!live) {
        msg.payload = Object.assign(state(), extra, { pushed: null });
        return msg;
    }
    return driver.applyCovPolicy().then(res => {
        msg.payload = Object.assign(state(), extra, { pushed: res });
        return msg;
    }).catch(e => {
        msg.payload = Object.assign(state(), extra, { pushed: { error: e.message } });
        return msg;
    });
}

const method = ((msg.req && msg.req.method) || 'GET').toUpperCase();

if (method === 'GET') {
    msg.payload = state();
    return msg;
}

const body = msg.payload || {};
const action = body.action;

try {
    switch (action) {
        case 'setProfile': {
            const r = cov.setProfile(body.profile);
            return pushAndRespond({ saved: r.profile.name, warnings: r.warnings });
        }
        case 'deleteProfile': {
            const r = cov.deleteProfile(body.name);
            return pushAndRespond({ deleted: r.deleted, overridesDropped: r.overridesDropped });
        }
        case 'setAssignments': {
            const r = cov.setAssignments(body.assignments);
            return pushAndRespond({ assignments: r.assignments, warnings: r.warnings });
        }
        case 'setOverride': {
            const r = cov.setOverride(body.pointId, body.profile === undefined ? null : body.profile);
            return pushAndRespond({ resolved: r });
        }
        // Les deux nombres de la confirmation, sans rien modifier.
        case 'preview': {
            msg.payload = Object.assign(state(), { preview: cov.preview(body.profile, body.pointIds || []) });
            return msg;
        }
        case 'applyToPoints': {
            const r = cov.applyToPoints(body.profile, body.pointIds || [], { overwriteManual: !!body.overwriteManual });
            return pushAndRespond({ applied: r });
        }
        // Réécrit tous les incréments dans l'appareil, même inchangés.
        case 'push': {
            if (!live) {
                msg.statusCode = 409;
                msg.payload = { error: 'aucun serveur BACnet connecté' };
                return msg;
            }
            return driver.applyCovPolicy({ force: true }).then(res => {
                msg.payload = Object.assign(state(), { pushed: res });
                return msg;
            });
        }
        default:
            msg.statusCode = 400;
            msg.payload = { error: "action attendue : setProfile | deleteProfile | setAssignments | setOverride | preview | applyToPoints | push" };
            return msg;
    }
} catch (e) {
    msg.statusCode = 400;
    msg.payload = { error: e.message };
    return msg;
}
